(() => {
  const inp = [...document.querySelectorAll('input')].find((x) => (x.placeholder || '').includes('选择所属行业'));
  if (!inp) return 'NO INPUT';
  const up = [];
  let e = inp;
  for (let i = 0; i < 6 && e; i++) { const r = e.getBoundingClientRect(); up.push({i: i, tag: e.tagName, cls: (e.className || '').toString().slice(0, 70), ka: e.getAttribute('ka') || '', w: Math.round(r.width), h: Math.round(r.height), x: Math.round(r.left), y: Math.round(r.top)}); e = e.parentElement; }
  const 中心 = document.elementFromPoint(Math.round(inp.getBoundingClientRect().left + inp.getBoundingClientRect().width / 2), Math.round(inp.getBoundingClientRect().top + inp.getBoundingClientRect().height / 2));
  return {祖先: up, 中心命中: 中心 ? (中心.tagName + '.' + (中心.className || '').toString().slice(0, 50) + '|ka=' + (中心.getAttribute('ka') || '')) : 'null', 外层HTML: inp.parentElement ? inp.parentElement.outerHTML.slice(0, 900) : ''};
})()
